function OverseaClubFeedCatUtils.GetParamValue(paramId)
    local result
    local row = CfUtils.GetCfLine(AutoIds.IdSetting6310, paramId)
    if row then
        result = CfUtils.GetCfDataByLine(row, "num",Constants.DataType.Int)
    else
        printError("神兽参数表中没有找到对应的参数id：%s", paramId)
    end

    return result
end

function OverseaClubFeedCatUtils.CalPetPhase(level)
    local row = checkTable(OverseaClubFeedCatUtils.GetExpVo(checkNumber(level)))
    return row.phase
end

