---@return ClubFeedCatTextVo
---@param phase number
---@param trigger number 触发条件（1.触摸，2.喂食）
function OverseaClubFeedCatUtils.GetTextVo(phase,trigger)
    local ids = CfUtils.GetIdGroupData(AutoIds.IdSetting6316, phase.."_"..trigger,"ids")
    if ids ~= nil and #ids >=1 then
        local id = ids[math.random(1,#ids)]
        return CfUtils.GetCfVo(AutoIds.IdSetting6316, "ClubFeedCatTextVo", id)
    end
end

function OverseaClubFeedCatUtils.SavePetsPhase(phase)
    local clubComp = ClubUtils.GetClubComp()
    GameUtils.SaveInt(PetPhaseRecordKey..clubComp:GetHomeDojo().clubId, phase)
end

function OverseaClubFeedCatUtils.GetLocalPetsPhase()
    local clubComp = ClubUtils.GetClubComp()
    return GameUtils.LoadInt(PetPhaseRecordKey..clubComp:GetHomeDojo().clubId, 1)
end

function OverseaClubFeedCatUtils.SaveInitialPlot()
