function OverseaClubFeedCatUtils.GetRefineConsum(part)
    local result = 0
    if part == 1 then
        result = OverseaClubFeedCatUtils.GetParamValue(OverseaClubFeedCatUtils.ParamsId.RefinePart1Cost)
    elseif part == 2 then
        result = OverseaClubFeedCatUtils.GetParamValue(OverseaClubFeedCatUtils.ParamsId.RefinePart2Cost)
    elseif part == 3 then
        result = OverseaClubFeedCatUtils.GetParamValue(OverseaClubFeedCatUtils.ParamsId.RefinePart3Cost)
    end
    return result
end

function OverseaClubFeedCatUtils.GetSkinPartName(part)
    if part == 1 then
        return localize("毛色")
    elseif part == 2 then
        return localize("颈饰")
    elseif part == 3 then
        return localize("尾饰")
    end
end

